CREATE TABLE nutrition_credentials(user_id TEXT PRIMARY KEY REFERENCES users(id),org_id TEXT NOT NULL REFERENCES organizations(id),registration TEXT NOT NULL,verified INTEGER NOT NULL CHECK(verified IN (0,1)),verified_by TEXT NOT NULL REFERENCES users(id),verified_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE nutrition_foods(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),author_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,preparation TEXT NOT NULL CHECK(preparation IN ('raw','cooked','as-sold')),composition TEXT NOT NULL,allergens TEXT NOT NULL,may_contain TEXT NOT NULL,provenance TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('draft','approved')),approved_by TEXT REFERENCES users(id),revision INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL);
CREATE TABLE nutrition_plans(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),student_id TEXT NOT NULL REFERENCES students(id),author_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,content TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('draft','review','approved','published')),approved_by TEXT REFERENCES users(id),approved_revision INTEGER,revision INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,published_at INTEGER);
CREATE TABLE nutrition_choices(plan_id TEXT NOT NULL REFERENCES nutrition_plans(id),student_id TEXT NOT NULL REFERENCES students(id),meal_index INTEGER NOT NULL,item_index INTEGER NOT NULL,option_index INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(plan_id,student_id,meal_index,item_index));
CREATE TABLE nutrition_requests(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),student_id TEXT NOT NULL REFERENCES students(id),plan_id TEXT NOT NULL REFERENCES nutrition_plans(id),meal_index INTEGER NOT NULL,item_index INTEGER NOT NULL,request TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','reviewed','declined')),response TEXT NOT NULL DEFAULT '',reviewed_by TEXT REFERENCES users(id),revision INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL);
CREATE INDEX nutrition_foods_org ON nutrition_foods(org_id,status);
CREATE INDEX nutrition_plans_student ON nutrition_plans(student_id,created_at);
CREATE INDEX nutrition_requests_student ON nutrition_requests(student_id,status);
